#!/usr/bin/env python3
# Derives schemas/motif-kit-4.schema.json from motif-kit-3 and adds the Sequencer layer data to motif-project.schema.json.
# python3 build/gen_schemas.py <schemas dir>
import json, sys, os, copy
d = sys.argv[1]
s = json.load(open(os.path.join(d, 'motif-kit-3.schema.json')))
s['$id'] = 'https://motif.local/schemas/motif-kit-4.schema.json'; s['title'] = s.get('title', 'Motif kit manifest').replace('3', '4') if False else s['title']
s['description'] = ('manifest.json of a .motifkit package. motif-kit@4 adds layer stacks (up to 3 media layers with blend modes and independent motion), svg inputs, '
  'text distance fields ("sdf": true on a text input), the vector shape / playhead / cue GLSL toolkit, the "vector" capability and kit-shipped sequences (motif-seq@1) to motif-kit@3. '
  'motif-kit@3 adds text inputs to motif-kit@2, which is a superset of motif-kit@1: every valid older manifest is accepted and read as before. The schema covers structure; the app additionally checks '
  'that files exist, GLSL analysis, generated-control name clashes, svg safety, sequence overlap limits and capability use.')
s['$comment'] = 'GENERATED by build/gen_schemas.py from schemas/motif-kit-3.schema.json and the motif-kit@4 rules in the kit-v4 module. Do not edit by hand.'
P = s['properties']
P['format']['enum'] = ['motif-kit@1', 'motif-kit@2', 'motif-kit@3', 'motif-kit@4']
P['capabilities']['items']['enum'] = ['media', 'audio', 'feedback', 'text', 'vector']
P['capabilities']['description'] = (P['capabilities'].get('description', '') + ' "vector": @4 only, svg inputs baked to distance fields on this device.').strip()
ID = {"type": "string", "pattern": "^[a-z][a-zA-Z0-9]{0,15}$", "not": {"enum": ["res", "p", "l", "seed", "safe", "bg", "ink", "a0", "a1", "a2", "buf0", "buf1", "buf2", "buf3", "out"]}}
D = s['$defs']
D['inputs'] = {"type": "array", "maxItems": 6, "description": "motif-kit@4: up to 2 media, 2 svg and 2 text inputs (earlier formats: 2 in total).",
  "items": {"if": {"required": ["type"], "properties": {"type": {"const": "text"}}}, "then": {"$ref": "#/$defs/textInput"},
            "else": {"if": {"required": ["type"], "properties": {"type": {"const": "svg"}}}, "then": {"$ref": "#/$defs/svgInput"}, "else": {"$ref": "#/$defs/mediaInput"}}}}
D['svgInput'] = {"type": "object", "required": ["id", "type", "src"], "additionalProperties": False, "description": "motif-kit@4. A vector file bundled in the kit, baked into a signed-distance texture; GLSL reads vec_<id>(uv).",
  "properties": {"id": ID, "type": {"const": "svg"}, "label": {"type": "string"}, "hint": {"type": "string"},
    "src": {"type": "string", "pattern": "^[A-Za-z0-9_][A-Za-z0-9_./-]{0,127}\\.svg$", "description": "Path of an .svg file in the kit (up to 64 KB: path, rect, circle, ellipse, line, polyline, polygon, g, transform, fill, stroke, fill-rule; no script, text, image, gradient, use or external reference)."},
    "spread": {"type": "number", "minimum": 8, "maximum": 64, "default": 24, "description": "Pixels of distance stored around the edge."},
    "margin": {"type": "number", "minimum": 0, "maximum": 0.4, "default": 0.08, "description": "Fraction of the frame kept clear around the artwork."}}}
tp = D['textInput']['properties']
tp['sdf'] = {"type": "boolean", "default": False, "description": "motif-kit@4. Also build a signed-distance field of the atlas; GLSL gets textDist_<id>(i, q)."}
tp['sdfSpread'] = {"type": "number", "minimum": 4, "maximum": 32, "default": 12, "description": "Pixels of distance stored around glyph edges in a 1024-wide field."}
BLEND = ['normal', 'multiply', 'screen', 'overlay', 'softlight', 'hardlight', 'add', 'darken', 'lighten', 'difference', 'exclusion', 'dodge']
D['style']['properties']['stack'] = {"type": "object", "additionalProperties": False, "description": "motif-kit@4. Up to 3 media layers inside one shader; generates inputs layer1..N and a block of controls per layer (opacity, blend, offset, scale, rotate, edges, cycles per loop, direction, travel).",
  "properties": {"layers": {"type": "integer", "minimum": 1, "maximum": 3, "default": 3}, "id": {"type": "string", "pattern": "^[a-z][a-zA-Z0-9]{0,9}$", "default": "layer"}, "fit": {"enum": ["fill", "fit", "stretch"], "default": "fill"},
    "labels": {"type": "array", "maxItems": 3, "items": {"type": "string", "maxLength": 20}}, "defaults": {"type": "array", "maxItems": 3, "items": {"type": "object", "additionalProperties": False, "properties": {"blend": {"enum": BLEND}}}}}}
TIME = {"oneOf": [{"type": "number"}, {"type": "string", "pattern": "^-?\\d+(\\.\\d+)?(/\\d+(\\.\\d+)?|%|s|b)?$"}], "description": "A fraction of the loop, or \"3/16\", \"25%\", \"1.5s\" (needs loop), \"2b\" (needs loop and bpm)."}
D['cue'] = {"type": "object", "required": ["style", "len"], "additionalProperties": False, "properties": {
  "id": {"type": "string", "pattern": "^[A-Za-z][\\w-]{0,23}$"}, "label": {"type": "string", "maxLength": 32}, "style": {"type": "string", "pattern": "^[A-Za-z0-9][\\w.-]{0,63}(/[A-Za-z0-9][\\w.-]{0,63})?$", "description": "A style of this kit (\"mitosis\") or of any installed kit (\"neuro/mitosis\")."},
  "at": TIME, "len": TIME, "lane": {"type": "integer", "minimum": 0, "maximum": 7}, "fadeIn": {"type": "number", "minimum": 0, "maximum": 0.5}, "fadeOut": {"type": "number", "minimum": 0, "maximum": 0.5},
  "cycles": {"type": "integer", "minimum": 1, "maximum": 8}, "dir": {"enum": ["forward", "backward", "pingpong", "random"]}, "blend": {"enum": BLEND}, "opacity": {"type": "number", "minimum": 0, "maximum": 1},
  "chance": {"type": "number", "minimum": 0, "maximum": 1}, "mute": {"type": "boolean"}, "seed": {"type": "integer", "minimum": 0, "maximum": 9999}, "palette": {"type": "string"},
  "params": {"type": "object", "maxProperties": 64, "additionalProperties": {"type": ["number", "string", "boolean"]}},
  "repeat": {"type": "object", "required": ["every", "count"], "additionalProperties": False, "properties": {"every": TIME, "count": {"type": "integer", "minimum": 2, "maximum": 16}}}}}
D['sequence'] = {"type": "object", "required": ["id"], "anyOf": [{"required": ["cues"]}, {"required": ["file"]}], "description": "motif-seq@1, inline or as { id, name, file }.", "properties": {
  "format": {"const": "motif-seq@1"}, "id": {"$ref": "#/$defs/id"}, "name": {"type": "string", "maxLength": 32}, "description": {"type": "string", "maxLength": 200}, "file": {"$ref": "#/$defs/file"},
  "loop": {"type": "number", "exclusiveMinimum": 0, "maximum": 600}, "bpm": {"type": "number", "minimum": 20, "maximum": 400}, "seed": {"type": "integer", "minimum": 1, "maximum": 9999}, "maxActive": {"type": "integer", "minimum": 1, "maximum": 4},
  "cues": {"type": "array", "minItems": 1, "maxItems": 64, "items": {"$ref": "#/$defs/cue"}}}}
P['sequences'] = {"type": "array", "maxItems": 8, "items": {"$ref": "#/$defs/sequence"}, "description": "motif-kit@4. Cue lists that call styles at points of the loop; they appear in the Sequencer layer's Load menu."}
# rules that mention @3: text inputs and the text capability are @3 and @4
txt = json.dumps(s['allOf']).replace('{"const": "motif-kit@3"}', '{"enum": ["motif-kit@3", "motif-kit@4"]}')
s['allOf'] = json.loads(txt)
s['allOf'].append({"if": {"not": {"properties": {"format": {"const": "motif-kit@4"}}}}, "then": {"not": {"anyOf": [{"required": ["sequences"]}]}}})
json.dump(s, open(os.path.join(d, 'motif-kit-4.schema.json'), 'w'), indent=2, ensure_ascii=False); open(os.path.join(d, 'motif-kit-4.schema.json'), 'a').write('\n')
# ---- project schema: the Sequencer layer's cue list
pp = os.path.join(d, 'motif-project.schema.json'); pr = json.load(open(pp)); lay = pr['$defs']['layer']
lay['properties']['styleId']['description'] = 'built-in style id, "<kit id>/<style id>" for a kit style, or "sequencer" (a Sequencer layer: its cues are in "seq")'
lay['properties']['seq'] = {"type": "object", "additionalProperties": False, "description": "Sequencer layer only (styleId \"sequencer\"): the cue list, as sanitised plain data. Times are fractions of the loop.", "required": ["cues"],
  "properties": {"id": {"type": "string", "maxLength": 32}, "name": {"type": "string", "maxLength": 32}, "seed": {"type": "integer", "minimum": 1, "maximum": 9999}, "maxActive": {"type": "integer", "minimum": 1, "maximum": 4},
    "cues": {"type": "array", "maxItems": 64, "items": {"type": "object", "additionalProperties": False, "required": ["id", "style", "at", "len"], "properties": {
      "id": {"type": "string"}, "i": {"type": "integer", "minimum": 0}, "style": {"type": "string"}, "at": {"type": "number", "minimum": 0, "maximum": 1}, "len": {"type": "number", "minimum": 0.01, "maximum": 1}, "lane": {"type": "integer", "minimum": 0, "maximum": 7},
      "fadeIn": {"type": "number", "minimum": 0, "maximum": 0.5}, "fadeOut": {"type": "number", "minimum": 0, "maximum": 0.5}, "cycles": {"type": "integer", "minimum": 1, "maximum": 8}, "dir": {"enum": ["forward", "backward", "pingpong", "random"]},
      "blend": {"enum": BLEND}, "opacity": {"type": "number", "minimum": 0, "maximum": 1}, "chance": {"type": "number", "minimum": 0, "maximum": 1}, "mute": {"type": "boolean"}, "seed": {"type": "integer", "minimum": 0, "maximum": 9999},
      "palette": {"type": ["string", "null"]}, "params": {"type": "object", "additionalProperties": {"type": ["number", "string", "boolean"]}}, "label": {"type": "string"}}}}}}
json.dump(pr, open(pp, 'w'), indent=2, ensure_ascii=False); open(pp, 'a').write('\n')
print('schemas written')
